constraints:
1 ≤ M, N ≤ 10^{5}
1 ≤ X[i], Y[i] ≤ 10^{3}

expected time complexity: O((N + M)log(N)).
expected auxiliary space: O(1).

standard_solution_code:
class Solution:

	def countPairs(self, a, b, M, N):
		from bisect import bisect as bi
		a.sort()
		b.sort()
		ans = 0
		for X in a:
			if X == 1:
				continue
			elif X == 2:
				ans += bi(b, 1) + N - bi(b, 4)
			elif X == 3:
				ans += bi(b, 2) + N - bi(b, 3)
			else:
				ans += bi(b, 1) + N - bi(b, X)
		return ans
